"""## Eliminar Archivos Generados"""

import os

# Lista de archivos que deseas eliminar
archivos_a_eliminar = [
    "audio.mp3",       # Nombre del archivo 1
    "audio.txt",       # Nombre del archivo 2 (por ejemplo, la transcripción)
    "audio.json",
    "audio.srt",
    "audio.tsv",
    "audio.vtt",
    "shortened_subtitles.srt"
    ]

# Eliminar los archivos especificados
for archivo in archivos_a_eliminar:
    if os.path.exists(archivo):
        os.remove(archivo)
        print(f"Archivo '{archivo}' eliminado.")
    else:
        print(f"El archivo '{archivo}' no existe o ya fue eliminado.")

